\title{Numerical approximation of a PDE--constrained Optimization problem that appears in  Data-Driven Computational Mechanics}

\date{}

\author[1]{Pedro B. Bazon}%\ead{pedro.bazon@usp.br}

\author[2*]{Cristian G. Gebhardt}%\ead{cristian.gebhardt@uib.no}

