\section{Proofs} \label{app:proofs}

\subsection{Averaging Node Features for Clusters' Features}
\begin{proposition}
    Setting cluster features as the average of the nodes they contain minimizes the Mean Squared Error (MSE) between the fully expanded hypergraph and the original hypergraph.
\end{proposition}

\begin{proof}
Let \( H = (\mathcal{V}, \mathcal{E}) \) be a hypergraph with node set \( \mathcal{V} \) and hyperedge set \( \mathcal{E} \), and let \( H_l = (\mathcal{V}_l, \mathcal{E}_l) \) denote the lifted hypergraph obtained by expanding each cluster \( \mathcal{C} \subseteq \mathcal{V} \) of size \(|C|\)-clique. By construction, there exists a bijection \( \phi : \mathcal{V} \to \mathcal{V}_l \) mapping each original node to its corresponding lifted node.
Suppose each node \( v \in \mathcal{V} \) is associated with a feature vector \( \mathbf{x}_v \in \mathbb{R}^d \), and each cluster \( \mathcal{C} \subseteq \mathcal{V} \) is assigned a cluster feature vector \( \mathbf{x}_\mathcal{C} \in \mathbb{R}^d \), which is inherited by all lifted nodes \( \phi(v) \) for \( v \in \mathcal{C} \).
Define the mean squared error between the original node features and the cluster features in the lifted hypergraph as:
\begin{equation}
\mathrm{MSE} = \sum_{v \in \mathcal{V}} \| \mathbf{x}_v - \mathbf{x}_{C(v)} \|^2,
\end{equation}
where \( C(v) \) denotes the cluster containing node \( v \).

To minimize the MSE, it suffices to minimize, for each cluster \( \mathcal{C} \),
\begin{equation}
J_\mathcal{C}(\mathbf{x}_\mathcal{C}) = \sum_{v \in \mathcal{C}} \| \mathbf{x}_v - \mathbf{x}_\mathcal{C} \|^2.
\end{equation}
Since \( J_\mathcal{C} \) is a convex quadratic function in \( \mathbf{x}_\mathcal{C} \), we find its minimum by setting the gradient to zero:
\begin{equation}
\nabla_{\mathbf{x}_\mathcal{C}} J_\mathcal{C}(\mathbf{x}_C) = \sum_{v \in \mathcal{C}} 2 (\mathbf{x}_\mathcal{C} - \mathbf{x}_v) = 2 |\mathcal{C}| \mathbf{x}_\mathcal{C} - 2 \sum_{v \in \mathcal{C}} \mathbf{x}_v = \mathbf{0}.
\end{equation}
Solving for \( \mathbf{x}_\mathcal{C} \), we obtain
\begin{equation}
\mathbf{x}_\mathcal{C} = \frac{1}{|\mathcal{C}|} \sum_{v \in \mathcal{C}} \mathbf{x}_v,
\end{equation}
which is the arithmetic mean of the feature vectors in the cluster \( \mathcal{C} \).
\end{proof}

\subsection{Minibatch OT-coupling}
Let $B$ be a bipartite graph.
Let $\mathbf{b}$ be its current budget repartition, $\mathbf{F}_L$ its node features, and $\mathbf{F}_R$ its hyperedge features.
Denote $\mathbf{x} = (\mathbf{v}_L, \mathbf{v}_R, \mathbf{e}, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}})$, \ie the predictions of the model.
In the following, all distributions are conditioned on $\mathbf{b}$, $\mathbf{F}_L$ and $\mathbf{F}_R$.

\begin{proposition}[Marginal preservation]
Under the OT-coupling of Algorithm~\ref{alg:minibatch_ot}, the joint distribution:
\[
q(\mathbf{x}_0, \mathbf{x}_1)
\]
has marginals:
\[
q_0(\mathbf{x}_0), \quad
q_1(\mathbf{x}_1).
\]
\end{proposition}

\begin{definition}[Isomorphism of bipartite graphs in our setting]
Let
\[
B_1 = (\mathcal{V}_L^1, \mathcal{V}_R^1, \mathcal{E}^1, \mathbf{b}^1, \mathbf{F}_L^1, \mathbf{F}_R^1), \quad
B_2 = (\mathcal{V}_L^2, \mathcal{V}_R^2, \mathcal{E}^2, \mathbf{b}^2, \mathbf{F}_L^2, \mathbf{F}_R^2),
\]
be bipartite graphs.

We say \( B_1 \cong B_2 \) (are isomorphic in our setting) if there exist bijections
\[
\sigma_L \colon \mathcal{V}_L^1 \to \mathcal{V}_L^2, \quad \sigma_R \colon \mathcal{V}_R^1 \to \mathcal{V}_R^2
\]
such that:
\begin{enumerate}[leftmargin=0.5cm]
    \itemsep0em 
    \item Edge structure is preserved: $(v, w) \in \mathcal{E}^1 \iff (\sigma_L(v), \sigma_R(w)) \in \mathcal{E}^2$,
    \item Budgets are preserved: $\mathbf{b}^1(v) = \mathbf{b}^2(\sigma_L(v)) \text{ for all } v \in \mathcal{V}_L^1, \quad
    \mathbf{b}^1(w) = \mathbf{b}^2(\sigma_R(w)) \text{ for all } w \in \mathcal{V}_R^1$,
    \item Node and hyperedge features are preserved: $
    \mathbf{F}_L^1(v) = \mathbf{F}_L^2(\sigma_L(v)), \quad
    \mathbf{F}_R^1(w) = \mathbf{F}_R^2(\sigma_R(w))$.
\end{enumerate}
\end{definition}

\begin{proof}
Let \( f \) be an arbitrary test function defined on bipartite graphs.
Algorithm \ref{alg:minibatch_ot} swaps noise samples between nodes that are equivalent in the sense that their target graphs (conditioned on the same topology and conditioning features) remain isomorphic after swapping. That is, if \( \mathbf{x}_0 \) and \( \mathbf{x}_0' \) differ only by such a swap, then the resulting graphs are isomorphic: \( B(\mathbf{x}_0) \cong B(\mathbf{x}_0') \).
Let \( \sigma \) be the bijective reindexing function corresponding to this isomorphism. Since \( f \) is defined on graphs and graphs are invariant under isomorphism, we have:
\[
f(\mathbf{x}_0) = f(\sigma(\mathbf{x}_0)).
\]
Therefore:
\begin{align}
\mathbb{E}_{q(\mathbf{x}_0, \mathbf{x}_1)}[f(\mathbf{x}_0)]
&= \mathbb{E}_{q(\mathbf{x}_1)} \left[ \mathbb{E}_{q(\mathbf{x}_0 \mid \mathbf{x}_1)}[f(\mathbf{x}_0)] \right] \\
&= \mathbb{E}_{q(\mathbf{x}_1)} \left[ \mathbb{E}_{q(\mathbf{x}_0)}[f(\sigma(\mathbf{x}_0))] \right] \\
&= \mathbb{E}_{q(\mathbf{x}_1)} \left[ \mathbb{E}_{q(\mathbf{x}_0)}[f(\mathbf{x}_0)] \right] \\
&= \mathbb{E}_{q(\mathbf{x}_0)}[f(\mathbf{x}_0)].
\end{align}
Thus, the marginal distribution over \( \mathbf{x}_0 \) remains unchanged. The same argument applies symmetrically for \( \mathbf{x}_1 \) by using \( \sigma^{-1} \), concluding the proof.
\end{proof}


\section{Complexity Analysis} \label{app:complexity}

In this section, we investigate the asymptotic complexity of our proposed algorithm, which extends the methodology introduced by \cite{bergmeister2024efficient} and \cite{gailhard2024hygenediffusionbasedhypergraphgeneration}.
To construct a hypergraph comprising $n$ nodes, $m$ hyperedges, and $k$ incidences, the algorithm sequentially produces a series of bipartite graphs $B^{(L)} = ( \{1\}, \{2\}, \{(1, 2)\} ), B^{(L-1)}, \dots, B^{(0)} = B$, where the final graph $B$ corresponds to the bipartite representation of the generated hypergraph.
We use $n$, $m$, and $k$ to denote, respectively, the number of nodes, hyperedges, and incidences in the hypergraph, and as the number of left-side nodes, right-side nodes, and edges in the corresponding bipartite graph.

For each level $0 \leq l < L$ of the sequence, the number of left-side nodes in $B^{(l)}$, denoted $n_l$, satisfies $n_l \geq (1+\epsilon)n_{l-1}$ for some $\epsilon > 0$ (\eg $\epsilon = \texttt{reduction\_frac} / (1 - \texttt{reduction\_frac})$). This implies an upper bound on the number of steps in the expansion sequence: $\lceil \log_{1+\epsilon} n \rceil \in \mathcal{O}(\log n)$.
Since the expansion process only increases node counts, all $B_l$ graphs contain fewer than $n$ left-side and $m$ right-side nodes. The number of edges, however, may temporarily exceed $k$, as the intermediate bipartite graphs may include additional edges removed in later refinements. Still, because the coarsening during training consistently reduces incidences, the model is expected to learn accurate edge refinement and avoid such accumulation. Consequently, we assume $k_l \leq k$ and $m_l \leq m$ for all $0 \leq l \leq L$.

Next, we assess the computational cost of generating a single expansion step. At level $l = L$, this consists of creating a pair of connected nodes, initializing features as matrices of zeros, initializing budget as the targeted node count, and predicting the expansion vectors $\mathbf{v}_L$ and $\mathbf{v}_R$—a process with constant complexity $\mathcal{O}(1)$.
For levels $0 \leq l < L$, given $B^{(l+1)}$ and expansion vectors $\mathbf{v}^{(l+1)}_L$, $\mathbf{v}^{(l+1)}_R$, the algorithm constructs the expanded bipartite graph $\Tilde{B}(B^{(l+1)}, \mathbf{v}_L^{(l+1)}, \mathbf{v}_R^{(l+1)})$ in $\mathcal{O}(n + m)$ time. It then samples $\mathbf{v}_L^{(l)}$, $\mathbf{v}_R^{(l)}$, $\mathbf{e}^{(l)}$, $\mathbf{f}$, $\mathbf{F}_L^{\text{refine}}$, and $\mathbf{F}_R^{\text{refine}}$, and constructs the refined graph $B^{(l)} = B(\Tilde{B}^{(l)}, \mathbf{e}^{(l)}, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}})$. Letting $v^L_{\max}$ and $v^R_{\max}$ be the maximum cluster sizes, the incidence count in $\Tilde{B}^{(l)}$ is bounded by $k_l \leq k_{l+1} v^L_{\max} v^R_{\max}$.

The sampling process queries a denoising model a constant number of times per step. The complexity is thus governed by the architecture. In our case, since bipartite graphs are triangle-free, the \textit{Local PPGN} model \cite{bergmeister2024efficient} has linear complexity $\mathcal{O}(n + m + k)$.
Embedding computation for $B^{(l)}$ similarly costs $\mathcal{O}(n + m + k)$. This includes calculating the top $K$ eigenvalues/eigenvectors of the Laplacian via the method from \cite{vishnoi2013lx}, with complexity $\mathcal{O}\left(K(n_{l+1} + m_{l+1} + k_{l+1})\right)$, and embedding via \textit{SignNet}, also linear in graph size due to fixed $K$.

The final transformation from the bipartite graph to a hypergraph—by collapsing right-side nodes into hyperedges—has a cost of $\mathcal{O}(m + k)$.
Under these assumptions, the total complexity to generate a hypergraph $H$ with $n$ nodes, $m$ hyperedges, and $k$ incidences is $\mathcal{O}(n + m + k)$.

\section{Coarsening Sequence Sampling} \label{app::coarsening}

This section outlines our methodology for sampling a coarsening sequence $\pi \in \Pi_F(H)$ for a given hypergraph $H$. The full procedure is detailed in Algorithm~\ref{alg::hypergraph_coarsening}.
At each coarsening step $l$, let $H^{(l)}$ denote the current hypergraph, $B^{(l)}$ its bipartite representation, and $C^{(l)}$ its weighted clique expansion. We begin by sampling a target reduction fraction $\text{red\_frac} \sim \mathcal{U}([\rho_\text{min}, \rho_\text{max}])$. We then evaluate all possible contraction sets $F(C^{(l-1)})$ using a cost function $c$, where lower cost indicates higher preference.
We employ a greedy randomized strategy that processes contraction sets in order of increasing cost. For each set:
\begin{itemize}[leftmargin=0.5cm]
    \itemsep0em 
    \item The set is stochastically rejected with probability $1 - \lambda$.
    \item If not rejected:
    \begin{itemize}
        \item \textbf{Overlap check:} If the contraction set overlaps with any previously accepted contraction, it is discarded.
        \item \textbf{Coarsening attempt:} Otherwise, we compute tentative coarsened representations $C_\text{temp}$ and $B_\text{temp}$.
        \item \textbf{Cluster constraint check:} If all right-side clusters in $B_\text{temp}$ contain at most three nodes, the contraction is accepted.
        \item \textbf{Update step:} When a contraction is accepted, we:
        \begin{itemize}
            \item Sum the budgets of the nodes in the contraction set to define the new cluster budget.
            \item Compute the new cluster's node features as a weighted average of the original features, using node budgets as weights.
        \end{itemize}
    \end{itemize}
\end{itemize}

The loop terminates once the number of remaining nodes satisfies the stopping condition:
\[
|\mathcal{V}_L^{(l-1)}| - |\bar{\mathcal{V}}_L^{(l)}| > \text{red\_frac} \cdot |\mathcal{V}_L^{(l-1)}|,
\]
\ie when the number of nodes on the left side (corresponding to the original hypergraph nodes) has been reduced by the sampled fraction.
This framework is flexible, allowing a variety of cost functions $c$, contraction families $F$, reduction fraction ranges $[\rho_\text{min}, \rho_\text{max}]$, and randomization parameters $\lambda$.

%\vspace{0.5cm}
\noindent \textbf{Practical considerations.} To avoid oversampling overly small graphs during training, we follow the heuristic of \cite{bergmeister2024efficient}: when the current graph has fewer than 16 nodes, we fix the reduction fraction to $\rho = \rho_\text{max}$.
Due to the constraint that no right-side cluster in $B^{(l)}$ may contain more than three nodes, achieving the target reduction fraction is not always feasible. However, we observe empirically that this rarely poses a problem when $\rho_\text{max}$ is reasonably small.

During training, we sample a coarsening sequence for each dataset graph, but only retain a randomly selected intermediate graph from the sequence. Thus, our practical implementation of Algorithm~\ref{alg::hypergraph_coarsening} is designed to return a single coarsened graph with associated features and budgets, rather than the full sequence $\pi$.

To improve efficiency, we incorporate the caching mechanism introduced in \cite{bergmeister2024efficient}. Once a coarsening sequence is generated, its levels are cached. During training, a random level is selected, returned, and then removed from the cache. A new sequence is generated only when the cache for a particular graph is depleted, avoiding unnecessary recomputation.

%\vspace{0.5cm}

\noindent \textbf{Hyperparameters}. 
In all experiments described in Section \ref{sec:experiments}, we use the following settings:
\begin{itemize}[leftmargin=0.5cm]
    \itemsep0em 
    \item Contraction family: The set of all edges in the clique representation, \ie $F(C) = \mathcal{E}$, for a weighted clique expansion $C = (\mathcal{V}, \mathcal{E})$.
    \item Cost function: Local Variation Cost \cite{loukas2018graph} with a preserving eigenspace size of $k = 8$.
    \item Reduction fraction range: $[\rho_\text{min}, \rho_\text{max}] = [0.1, 0.3]$.
\end{itemize}

\begin{algorithm*}[hbtp]
\caption{\textbf{Hypergraph coarsening sequence sampling}: Randomized iterative coarsening of a hypergraph. At each step, contraction sets are selected based on cost, while ensuring right-side clusters never merge more than three at a time. Accepted contractions update the hypergraph structure, node budgets, and features.}
\label{alg::hypergraph_coarsening}
\begin{algorithmic}[1]
\Parameters contraction family $F$, cost function $c$, reduction fraction range $[\rho_\text{min}, \rho_\text{max}]$, randomization parameter $\lambda$
\Input hypergraph $H$ with $n$ nodes and $m$ hyperedges; node features $\mathbf{F}_L$; hyperedge features $\mathbf{F}_R$
\Output coarsening sequence $\pi = (H^{(0)}, \ldots, H^{(L)}) \in \Pi_F(H)$
\Function{HypergraphCoarseningSeq}{$H$}
    \State $H^{(0)} \gets H$
    \State $B^{(0)} \gets \text{BipartiteRepresentation}(H^{(0)})$
    \State $C^{(0)} \gets \text{WeightedCliqueExpansion}(H^{(0)})$
    \State $\mathbf{b}_L^{(0)} \gets (1, \dots, 1) \in \mathbb{R}^n$ \Comment{Initial node budgets}
    \State $\mathbf{b}_R^{(0)} \gets (1, \dots, 1) \in \mathbb{R}^m$ \Comment{Initial hyperedge budgets}
    \State $\pi \gets (B^{(0)}, \mathbf{b}_L^{(0)}, \mathbf{F}_L, \mathbf{F}_R)$
    \State $l \gets 0$

    \While{$|\mathcal{V}_L^{(l)}| > 1$}
        \State $l \gets l + 1$
        \State $\text{red\_frac} \sim \text{Uniform}([\rho_\text{min}, \rho_\text{max}])$ \Comment{Sample reduction fraction}
        \State $f \gets c(\cdot, C^{(l-1)}, (\mathcal{P}^{(l-1)}, \ldots, \mathcal{P}^{(0)}))$ \Comment{Cost function}
        \State $\text{accepted\_contractions} \gets \emptyset$

        \For{$S \in \text{SortedByCost}(F(C^{(l-1)}))$}
            \If{$\text{Random}() > \lambda$}
                \If{$S \cap (\bigcup_{P \in \text{accepted\_contractions}} P) = \emptyset$}
                    \State $C_\text{temp} \gets \text{CoarsenCliqueExpansion}(C^{(l-1)}, S)$
                    \State $B_\text{temp} \gets \text{CoarsenBipartite}(B^{(l-1)}, S)$

                    \If{$\forall \text{ right cluster } R \in B_\text{temp}: |R| \leq 3$}
                        \State $\text{accepted\_contractions} \gets \text{accepted\_contractions} \cup \{S\}$
                        \State $C^{(l)} \gets C_\text{temp}$, $B^{(l)} \gets B_\text{temp}$

                        \Statex \Comment{\textit{Update budgets and features for the new cluster}}
                        \State $\text{Let } S = \{v_1, \ldots, v_k\}, \text{ and the new node be } v^*$
                        \State $\mathbf{b}_L^{(l)}[v^*] \gets \sum_{i=1}^k \mathbf{b}_L^{(l-1)}[v_i]$
                        \State $\mathbf{F}_L^{(l)}[v^*] \gets \frac{1}{\mathbf{b}_L^{(l)}[v^*]} \sum_{i=1}^k \mathbf{b}_L^{(l-1)}[v_i] \cdot \mathbf{F}_L^{(l-1)}[v_i]$
                    \EndIf
                \EndIf
            \EndIf
            \If{$|\mathcal{V}_L^{(l-1)}| - |\bar{\mathcal{V}}_L^{(l)}| > \text{red\_frac} \cdot |\mathcal{V}_L^{(l-1)}|$}
                \State \textbf{break}
            \EndIf
        \EndFor
        \State $\pi \gets \pi \cup \{B^{(l)}, \mathbf{b}_L^{(l)}, \mathbf{F}_L^{(l)}\}$
    \EndWhile

    \State \Return $\pi$
\EndFunction
\end{algorithmic}
\end{algorithm*}


