\section{Training and Sampling Procedures} \label{app::training_sampling}

In this section, we present the complete training and inference procedures, detailed in Algorithms~\ref{alg::train} and~\ref{alg::sample_deterministic}.
Both pipelines rely on node embeddings produced by Algorithm~\ref{alg::embeddings}.

\begin{algorithm*}[hbtp]
\caption{\textbf{Node embedding computation:} Here we describe the way the left and right side node embeddings are computed for a given bipartite representation of a hypergraph. Embeddings are computed for the input bipartite representation and then replicated according to the cluster size vectors.}
\label{alg::embeddings}
\begin{algorithmic}[1]
\Parameters number of spectral features $k$
\Input bipartite representation $B = (\mathcal{V}_L, \mathcal{V}_R, \mathcal{E})$, spectral feature model SignNet$_\theta$, cluster size vector $\mathbf{v}_L$ and $\mathbf{v}_R$
\Output node embeddings computed for all nodes in $\mathcal{V}_L$ and $\mathcal{V}_R$ and replicated according to $\mathbf{v}_L$ and $\mathbf{v}_R$
\Function{Embeddings}{$B = (\mathcal{V}_L, \mathcal{V}_R, \mathcal{E})$, SignNet$_\theta$, $\mathbf{v}_L$, $\mathbf{v}_R$}
    \If{$k = 0$}
        \State $\mathbf{H} = [h^{(1)}, \ldots, h^{(|\mathcal{V}|)}] \overset{i.i.d.}{\sim} \mathcal{N}(0, I)$ \Comment{Sample random embeddings}
    \Else
        \If{$k < |\mathcal{V}|$}
            \State $[\lambda_1, \ldots, \lambda_k], [u_1, \ldots, u_k] \gets \text{EIG}(B)$ \Comment{Compute $k$ spectral features}
        \Else
            \State $[\lambda_1, \ldots, \lambda_{|\mathcal{V}_L|+|\mathcal{V}_R|-1}], [u_1, \ldots, u_{|\mathcal{V}_L|+|\mathcal{V}_R|-1}] \gets \text{EIG}(B)$ \Comment{Compute $|\mathcal{V}_L| + |\mathcal{V}_R| - 1$ spectral features}
            \State $[\lambda_{|\mathcal{V}_L| + |\mathcal{V}_R|}, \ldots, \lambda_k], [u_{|\mathcal{V}_L| + |\mathcal{V}_R|}, \ldots, u_k] \gets [0, \ldots, 0], [0, \ldots, 0]$ \Comment{Pad with zeros}
        \EndIf
        \State $\mathbf{H} = [h^{(1)}, \ldots, h^{(|\mathcal{V}_L| + |\mathcal{V}_R|)}] \gets \text{SignNet}_\theta([\lambda_1, \ldots, \lambda_k], [u_1, \ldots, u_k], B)$
    \EndIf
    \State $\tilde{B} = (\mathcal{V}_L^{(1)} \cup \cdots \cup \mathcal{V}_L^{(p_l)}, \mathcal{V}_R^{(1)} \cup \cdots \cup \mathcal{V}_R^{(p_r)}, \tilde{\mathcal{E}}) \gets \tilde{B}(B, \mathbf{v}_L, \mathbf{v}_R)$ \Comment{Expand as per Definition \ref{def::expansion}}
    \State set $\tilde{B}$ s.t. for all $p_L \in [|\mathcal{V}_L|]$ and all $p_R \in [|\mathcal{V}_R|]$: for all $\mathbf{v}_L^{(p_i)} \in \mathcal{V}_L^{(p_l)}$, $\tilde{\mathbf{H}}[p_i] = \mathbf{H}[p_l]$ and for all $\mathbf{v}_R^{(p_i)} \in \mathcal{V}_R^{(p_r)}$, $\tilde{\mathbf{H}}[p_i] = \mathbf{H}[p_r]$ \Comment{Replicate embeddings}
    \State \Return $\tilde{\mathbf{H}}$
\EndFunction
\end{algorithmic}
\end{algorithm*}

\begin{algorithm*}[htbp]
\caption{\textbf{End-to-end training procedure:} This describes the entire training procedure for our
model.}
\label{alg::train}
\begin{algorithmic}[1]
\Parameters number of spectral features $k$ for node embeddings
\Input dataset $\mathcal{D} = \{H_1, \ldots, H_N\}$, denoising model GNN$_\theta$, spectral feature model SignNet$_\theta$
\Output trained model parameters $\theta$
\Function{Train}{$\mathcal{D}$, GNN$_\theta$, SignNet$_\theta$}
    \While{not converged}
        \State $H \sim \text{Uniform}(\mathcal{D})$ \Comment{Sample graph}
        \State $(B^{(0)}, \ldots, B^{(L)}) \gets \text{RndRedSeq}(H)$ \Comment{Sample coarsening sequence by Algorithm \ref{alg::hypergraph_coarsening}}
        \State $l \sim \text{Uniform}(\{0, \ldots, L\})$ \Comment{Sample level}
        \If{$l = 0$}
            \State $\mathbf{v}_L^{(0)} \gets 1$, $\mathbf{v}_R^{(0)} \gets 1$
        \Else
            \State set $\mathbf{v}_L^{(l)}$ and $\mathbf{v}_R^{(l)}$ such that the node sets of $\tilde{B}(B^{(l)}, \mathbf{v}_L^{(l)}, \mathbf{v}_R^{(l)})$ equals that of $B^{(l-1)}$
        \EndIf

        \If{$l = L$}
            \State $B^{(l+1)} \gets B^{(l)} = ( \{1\}, \{2\}, \{ (1, 2)\}, \mathbf{b}=size(H), \mathbf{F}_L=0, \mathbf{F}_R=0)$
            \State $\mathbf{v}_L^{(l+1)} \gets 1$
            \State $\mathbf{v}_R^{(l+1)} \gets 1$
            \State $\mathbf{e}^{(l)} \gets 1$
        \EndIf

        \State set $\mathbf{e}^{(l)}$, $\mathbf{f}$, $\mathbf{F}_L^{\text{refine}}$ and $\mathbf{F}_R^{\text{refine}}$ such that $B(\tilde{B}(B^{(l+1)}, \mathbf{v}_L^{(l+1)}, \mathbf{v}_R^{(l+1)}), \mathbf{e}^{(l)}, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}}) = B^{(L)}$

        \State $\mathbf{H}^{(l)} \gets \text{Embeddings}(B^{(l+1)}, \text{SignNet}_\theta, \mathbf{v}_L^{(l+1)}, \mathbf{v}_R^{(l+1)})$ \Comment{Compute node embeddings}
        \State $\hat{\rho} \gets 1 - (n^{(l)}/n^{(l-1)})$, with $n^{(l)}$ and $n^{(l-1)}$ being the size of the left side of $B^{(l)}$ and $B^{(l-1)}$
        \State $D_\theta \gets \text{GNN}_\theta(\cdot, \cdot, \tilde{B}^{(l)}, \mathbf{H}^{(l)}, n^{(0)}, \rho)$, where $n^{(0)}$ is the size of the left side of $B^{(0)}$
        \State take gradient descent step on $\nabla_\theta \text{DiffusionLoss}(\mathbf{v}_L^{(L)}, \mathbf{v}_R^{(L)}, \mathbf{e}^{(l)}, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}}, D_\theta)$
    \EndWhile
    \State \Return $\theta$
\EndFunction
\end{algorithmic}
\end{algorithm*}

\begin{algorithm*}[htbp]
\caption{\textbf{End-to-end sampling procedure with deterministic expansion size:} This describes the sampling procedure. Note that this assumes that the maximum cluster sizes are 2 and 3, which is the case when using edges of the clique representation as the contraction set family for model training.}
\label{alg::sample_deterministic}
\begin{algorithmic}[1]
\Parameters reduction fraction range $[\rho_\text{min}, \rho_\text{max}]$
\Input target hypergraph size $N$, denoising model GNN$_\theta$, spectral feature model SignNet$_\theta$
\Output sampled hypergraph $H = (\mathcal{V}, \mathcal{E})$ with $|\mathcal{V}| = N$
\Function{Sample}{$N$, GNN$_\theta$, SignNet$_\theta$}
    \State $B = (\mathcal{V}_L, \mathcal{V}_R, \mathcal{E}, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}}) \gets (\{1\}, \{2\}, \{(1, 2)\}, N, 0, 0)$ \Comment{Start with a minimal bipartite graph}
    \State $\mathbf{v}_L \gets [1]$, $\mathbf{v}_R \gets [1]$ \Comment{Initial cluster size vectors}
    \While{$|\mathcal{V}_L| < N$}
        \State $\mathbf{H} \gets \text{Embeddings}(B, \text{SignNet}_\theta, \mathbf{v}_L, \mathbf{v}_R)$ \Comment{Compute node embeddings}
        \State $n \gets \|\mathbf{v}_L\|_1$
        \State $\rho \sim \text{Uniform}([\rho_\text{min}, \rho_\text{max}])$ \Comment{random reduction fraction}
        \State set $n^+$ s.t. $n^+ = \lceil\rho(n + n^+)\rceil$ \Comment{number of left side nodes to add}
        \State $n^+ \gets \min(n^+, N - n)$ \Comment{ensure not to exceed target size}
        \State $\hat{\rho} \gets 1 - (n/(n + n^+))$ \Comment{actual reduction fraction}
        \State $D_\theta \gets \text{GNN}_\theta(\cdot, \cdot, \tilde{B}(B, \mathbf{v}_L, \mathbf{v}_R), \mathbf{H}, N, \hat{\rho})$
        \State $(\mathbf{v}_L)_0, (\mathbf{v}_R)_0, (\mathbf{e})_0, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}} \gets \text{Sample}(D_\theta)$ \Comment{Sample features}
        \State set $\mathbf{v}_L$ s.t. for $i \in [n]$: $\mathbf{v}_L[i] = 2$ if $|\{j \in [n] \mid (\mathbf{v}_L)_0[j] \geq (\mathbf{v}_L)_0[i]\}| \geq n^+$ and $v[i] = 1$ otherwise
        \State set $\mathbf{v}_R$ s.t. for $i \in [|(\mathbf{v}_R)_0|]$: $\mathbf{v}_R[i] = 1$ if $(\mathbf{v}_R)_0 < 1.66$, $\mathbf{v}_R[i] = 2$ if $(\mathbf{v}_R)_0 < 2.33$ and $\mathbf{v}_R[i] = 3$ otherwise
        \State set $\mathbf{e}$ s.t. for $i \in [|(\mathbf{e})_0|]$: $\mathbf{e}[i] = 1$ if $(\mathbf{e})_0 > 0.5$ and $\mathbf{e}[i] = 0$ otherwise
        \State $B = (\mathcal{V}_L, \mathcal{V}_R, \mathcal{E}) \gets B(\tilde{B}, \mathbf{e}, \mathbf{f}, \mathbf{F}_L^{\text{refine}}, \mathbf{F}_R^{\text{refine}})$ \Comment{Refine as per Definition \ref{def::refinement}}
    \EndWhile
    \State build $H$ from its bipartite representation $B$
    \State \Return $H$
\EndFunction
\end{algorithmic}
\end{algorithm*}

