\begin{observation}[Derivability of Transitivity]
For ET, WT, and AT \textit{Transitivity} is derivable from \textit{Teakening} and \textit{Transitivity'}.
\end{observation}

\begin{proof}
The (simple) proof is as follows:
\begin{prooftree}
\AxiomC{$\textgoth{a} \overset{XT}{{\underset{m}{\leadsto}}} \textgoth{b}$}
\RightLabel{Weakening}
\UnaryInfC{$\textgoth{a} \overset{XT}{{\underset{min(m,l)}{\leadsto}}} \textgoth{b}$}

\AxiomC{$\textgoth{b} \overset{XT}{{\underset{l}{\leadsto}}} \textgoth{c}$}
\RightLabel{Weakening}
\UnaryInfC{$\textgoth{b} \overset{XT}{{\underset{min(m,l)}{\leadsto}}} \textgoth{c}$}

\RightLabel{Transitivity$^\prime$}
\BinaryInfC{$\textgoth{a} \overset{XT}{{\underset{min(m,l)}{\leadsto}}} \textgoth{c}$}
\end{prooftree}
\end{proof}

\begin{observation}[Derivability of \textit{m=n to Top}]
