\section{Special cases: constraints on weights and proximity matrix to improve the efficiency of the algorithm}

To reduce the complexity of the algorithm, algebraic conditions can be imposed on both the proximity matrix and the weights associated with the length of the paths.
The trivial case is when the weights associated with the path lengths are constant, $W.$ In this case the distance coincides with the weighted path metric (see \cite{deza}, p.258) multiplied by the constant $W.$ Therefore, the calculation of the distance can be performed using the Bellman-Ford or Dijkstra algorithms.

In this section we will consider the weights associated with the inverse of a power of the lengths of the paths $W:=\left\{\frac{1}{t^k}\right\}_{t=1}^\infty$, with the power $k$ greater than or equal to $1$. The importance of these weights lies in the fact that it is the natural generalization of the  case when the power is equal to $1$, the distance between nodes coincides with the average of the path weights. This class of weights, that have been already used in the previous sections as general examples, is also relevant for applications (see \cite{cal}).

The results provided in this section can be implemented directly in the algorithm to make it faster. We explain the requirements that have to be met, as well as the procedures for using them. 

\begin{Proposition}\label{prop:Pareto2}
	Consider a graph $G = (V,E)$ and the weights associated to the lengths of the paths $W:=\left\{\frac{1}{t^k}\right\}_{t=1}^\infty$, with $k \geq 1$.
	Fix $a, b \in V$ and let $P, P' \in \mathcal P(a,b)$ such that $l(P) \geq l(P')$ and $d(P) \leq d(P')$.
	Then, for any $c \in V$ and $R \in \mathcal P(b,c)$ such that $d(P') \leq d(R)$, we have that the paths $Q = P \sqcup R$ and $Q' = P' \sqcup R$ in $\mathcal P(a,c)$ satisfy $d(Q) \leq d(Q')$.
\end{Proposition}

\begin{proof}
	Consider $P = (x_0, x_1, \ldots, x_n)$, $P' = (x_0', x_1', \ldots, x_m')$ and $R = (y_0, y_1, \ldots, y_r)$ as in the statement so that $l(P) = n$, $l(P') = m$ and $l(R) = r$.
	Then,
	\begin{align*}
		d(Q) &= d(P \sqcup R) = \frac{\sum_{i=1}^n \phi(x_{i-1}, x_i) + \sum_{i=1}^r \phi(y_{i-1},y_i)}{\left(n + r\right)^k} = \frac{n \cdot d(P) + r \cdot d(R)}{\left(n + r\right)^k}, \\
		d(Q') &= \frac{m \cdot d(P') + r \cdot d(R)}{\left(m + r\right)^k}.
	\end{align*}
	Then by hypothesis,
	\begin{align*}
		d(P) &\leq \frac{m \cdot d(P')}{m} = \\
		&= \frac{m}{n \cdot m} \left(m \cdot d(P') \right) + \frac{n-m}{n \cdot m} \left(m \cdot d(P') \right) \leq \\
		&\leq \frac{m \cdot d(P')}{n} + \frac{n-m}{n} d(R).
	\end{align*}
	That implies that $n \cdot d(P) \leq m \cdot d(P') + (n-m) d(R)$. Therefore,
	\begin{align*}
		\left(n + r\right)^k (m+r)d(Q) &= \left(n + r\right)^k (m+r) \left( \frac{n \cdot d(P) + r \cdot d(R)}{\left(n + r\right)^k} \right) = \\
		&= n \cdot m \cdot d(P) + n \cdot r \cdot d(P) + (m+r) (r \cdot d(R)) \leq \\
		&\leq n \cdot m \cdot d(P') + r \cdot m \cdot d(P') + (n-m) (r \cdot d(R)) + (m+r) (r \cdot d(R)) = \\
		&= (n+r) \left( m \cdot d(P') + r \cdot d(R) \right) = \\
		&= (n+r)\left(m + r\right)^k d(Q') \leq \\
		&\leq  \left( \frac{n+r}{m+r} \right)^{k-1} (n+r)\left(m + r\right)^k d(Q') = \\
		&= \left(n + r\right)^k (m+r) d(Q'),
	\end{align*}
	so $d(Q) \leq d(Q')$.
\end{proof}


\begin{Proposition}\label{prop:Pareto3}
	Consider a graph $G = (V,E)$ and the weights associated to the lengths of the paths $W:=\left\{\frac{1}{t^k}\right\}_{t=1}^\infty$, with $k \geq 1$.
	Fix $a, b \in V$ and let $P, P' \in \mathcal P(a,b)$ such that $l(P) \leq l(P')$ and $d(P) \leq d(P')$.
	Then, for any $c \in V$ and $R \in \mathcal P(b,c)$ such that $d(R) \leq d(P)$, we have that the paths $Q = P \sqcup R$ and $Q' = P' \sqcup R$ in $\mathcal P(a,c)$ satisfy $d(Q) \leq d(Q')$.
\end{Proposition}

The proof of this result is analogous to Proposition \ref{prop:Pareto2}, so it will be omitted.


\textit{Remark.}
It is trivial that Propositions \ref{prop:Pareto2} and \ref{prop:Pareto3} also work if the paths $Q = R \sqcup P$ and $Q' = R \sqcup P'$ in $\mathcal P(a,c)$ are used, being in this case $R \in \mathcal P(a,b)$ and $P, P' \in \mathcal P(b,c)$.



These propositions suggest to define in $\mathcal P(a,b)$ and for each $R \in \mathcal P(b,c)$ the order relation $P \preceq_{R}^1 Q$  given by the conditions
\begin{equation*}
	l(P) \geq l(Q) \ \ \text{and} \ \ d(P) \leq d(Q) \leq d(R)
\end{equation*}
(suggested by Proposition \ref{prop:Pareto2}), and the order relation $P \preceq_{R}^2 Q$ given by
\begin{equation*}
	l(P) \leq l(Q) \ \ \text{and} \ \ d(R) \leq d(P) \leq d(Q)
\end{equation*}
(suggested by Proposition \ref{prop:Pareto3}).

As can be seen, these order relations are more restrictive than the order relation $\preceq$ defined in the previous sections (although they depend on the path $R$), since they are given as a function of the distance $d$ while $\preceq$ is a function of the sum of the weights $s$.

To reduce the set of paths suitable for calculating the distance with our algorithm using these order relations we need them to not depend on the path $R$. This can be done by imposing some additional properties to the graph. In particular, this works if  the graph meets one of the following conditions, that are different depending on the order relation we will use. 

\begin{itemize}
	\item[1] \textit{Requirements for the order $\preceq_{R}^1$.}  Let $G = (V,E)$ be a weighted directed graph with no cycles. The condition we impose in this case is the following: for all $a,b,c$ in $V$, with $\mathcal P(a,b)$ nonempty and $b$ connected to $c$ ---that is $(b,c) \in E$---, the inequality
	\begin{equation}\label{eq:condition2}
		d(P) \leq \phi(b,c)
	\end{equation}
	holds for all $P \in \mathcal P(a,b)$.  Note that this requirement is independent of $R$, so we write 
	$\preceq^1$ for the associate order relation.
	As it is not always possible to verify this condition given a graph, we will check that for all $(a,b), (b,c) \in E$ it is satisfied that
	\begin{equation}\label{eq:condition2_2}
		\phi(a,b) \leq \phi(b,c).
	\end{equation}
	It is obvious that  this condition implies \ref{eq:condition2}.
	Using this, we can simplify the algorithm. Clearly, in this case it is enough to explore the paths of the following Pareto front
	\begin{equation}\label{set:filter_path2}
		\mathcal P_{1}^{*}(a,b) = \left\{ P \in \mathcal P(a,b): \{ P' \in \mathcal P(a,b): P' \preceq^1 P, P \neq P' \} = \emptyset \right\}.
	\end{equation}


	\item[2] \textit{Requirements for the order $\preceq_{R}^2.$} As above, let $G = (V,E)$ be a weighted directed graph with no cycles. The requirement is in this case the following: for all $a,b,c$ in $V$, with $\mathcal P(a,b)$ nonempty and $b$ connected to $c$ ---that is $(b,c) \in E$---,  the inequality
	\begin{equation}\label{eq:condition3}
		d(P) \geq \phi(b,c)
	\end{equation}
	has to be satisfied for all $P \in \mathcal P(a,b)$. 
	A sufficient condition to be checked is that for all $(a,b), (b,c) \in E$ it is satisfied that $\phi(a,b) \geq \phi(b,c).$ Again, this implies  \ref{eq:condition3}.
	In this case it is enough to consider the  paths: 
	\begin{equation}\label{set:filter_path3}
		\mathcal P_{2}^{*}(a,b) = \left\{ P \in \mathcal P(a,b): \{ P' \in \mathcal P(a,b): P' \preceq^2 P, P \neq P' \} = \emptyset \right\}.
	\end{equation}
\end{itemize}



